2	
3	const ROUNDS = 5;        // rounds per mode
4	const TO_PASS = 4;       // correct answers needed for the badge
5	const BADGES = { easy: "🐟 Minnow", medium: "🎣 Angler", hard: "⚓ Captain" };
6	const MISSIONS = {
7	  easy: "Warm-up shift. These scams are obvious: watch for typos, surprise prizes, and ALL CAPS urgency.",
8	  medium: "Scammers are getting smarter. Check every sender address and phone number against the real ones above.",
9	  hard: "Expert level. Some scams look perfect, and some real emails look scary. Read every detail before you decide.",
10	};
11	
12	let mode, round, correct, current, seen;
13	
14	const $ = (id) => document.getElementById(id);
15	const show = (id) => {
16	  ["start-screen", "mission-screen", "play-screen", "end-screen"].forEach((s) => $(s).classList.add("hidden"));
17	  $(id).classList.remove("hidden");
18	};
19	const esc = (t) => String(t ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
20	
21	// ---------- Talking to the backend ----------
22	// Practice mode: if the backend isn't running (opened as a file, Live Server,
23	// or a static host like Vercel), the game uses mock-data.js instead.
24	let OFFLINE = location.protocol === "file:";
25	
26	async function checkBackend() {
27	  if (OFFLINE) return;
28	  try {
29	    const r = await fetch("/api/leaderboard");
30	    if (!r.ok) throw new Error("no backend");
31	    await r.json();
32	  } catch (e) {
33	    OFFLINE = true;
34	  }
35	}
36	
37	async function apiGetScenario(mode, seen) {
38	  if (OFFLINE) {
39	    const pool = MOCK_SCENARIOS.filter((s) => s.difficulty === mode && !seen.includes(s.scenario_id));
40	    const s = pool[Math.floor(Math.random() * pool.length)];
41	    return { scenario_id: s.scenario_id, channel: s.channel, sender: s.sender, subject: s.subject, body: s.body, link: s.link };
42	  }
43	  return fetch(`/api/scenario?mode=${mode}&seen=${seen.join(",")}`).then((r) => r.json());
44	}
45	
46	async function apiAnswer(scenario_id, guess) {
47	  if (OFFLINE) {
48	    const s = MOCK_SCENARIOS.find((x) => x.scenario_id === scenario_id);
49	    return { correct: guess === s.game_answer, game_answer: s.game_answer, red_flags: s.red_flags, explanation: s.explanation };
50	  }
51	  return fetch("/api/answer", {
52	    method: "POST",
53	    headers: { "Content-Type": "application/json" },
54	    body: JSON.stringify({ scenario_id, guess }),
55	  }).then((r) => r.json());
56	}
57	
58	async function apiSaveScore(username, points, badge) {
59	  if (OFFLINE) {
60	    const board = JSON.parse(localStorage.getItem("ps-board") || "{}");
61	    const p = board[username] || { username, total_score: 0, badges: [] };
62	    p.total_score += points;
63	    if (badge && !p.badges.includes(badge)) p.badges.push(badge);
64	    board[username] = p;
65	    try { localStorage.setItem("ps-board", JSON.stringify(board)); } catch (e) {}
66	    return p;
67	  }
68	  return fetch("/api/score", {
69	    method: "POST",
70	    headers: { "Content-Type": "application/json" },
71	    body: JSON.stringify({ username, points, badge }),
72	  }).then((r) => r.json());
73	}
74	
75	async function apiLeaderboard() {
76	  if (OFFLINE) {
77	    let board = {};
78	    try { board = JSON.parse(localStorage.getItem("ps-board") || "{}"); } catch (e) {}
79	    return Object.values(board)
80	      .sort((a, b) => b.badges.length - a.badges.length || b.total_score - a.total_score)
81	      .slice(0, 10);
82	  }
83	  return fetch("/api/leaderboard").then((r) => r.json());
84	}
