86	// ---------- Start: pick a difficulty, then see the mission ----------
87	document.querySelectorAll(".mode").forEach((btn) =>
88	  btn.addEventListener("click", () => {
89	    if (!$("username").value.trim()) return $("username").focus();
90	    mode = btn.dataset.mode;
91	    const label = mode.charAt(0).toUpperCase() + mode.slice(1);
92	    $("mission-mode").textContent = `${label} mode · ${BADGES[mode]} badge`;
