98	$("btn-back").addEventListener("click", () => show("start-screen"));
99	
100	$("btn-start").addEventListener("click", () => {
101	  round = 0;
102	  correct = 0;
103	  seen = [];
104	  show("play-screen");
105	  nextRound();
106	});
