108	// ---------- Play ----------
109	async function nextRound() {
110	  await ready;
111	  round++;
112	  $("progress").textContent = `${mode.toUpperCase()} · Round ${round} of ${ROUNDS} · ${correct} correct`;
113	  $("result").classList.add("hidden");
114	  $("btn-next").classList.add("hidden");
115	  $("btn-phish").disabled = $("btn-legit").disabled = true;
116	  $("message").innerHTML = `<p class="loading">Loading message...</p>`;
117	
118	  current = await apiGetScenario(mode, seen);
119	  seen.push(current.scenario_id);
120	  $("message").innerHTML = renderMessage(current);
121	  $("btn-phish").disabled = $("btn-legit").disabled = false;
122	}
123	
124	function renderMessage(s) {
125	  // Links are shown as plain text on purpose: never clickable.
126	  const link = s.link ? `<p class="link">🔗 ${esc(s.link)}</p>` : "";
127	  if (s.channel === "sms") {
128	    return `<div class="sms">
129	      <p class="label">💬 Text message from <b>${esc(s.sender)}</b></p>
130	      <p class="bubble">${esc(s.body)}</p>${link}</div>`;
131	  }
132	  return `<div class="email">
133	    <p class="label">✉️ <b>From:</b> ${esc(s.sender)}</p>
134	    <p class="label"><b>Subject:</b> ${esc(s.subject)}</p>
135	    <p class="body">${esc(s.body)}</p>${link}</div>`;
136	}
137	
138	async function answer(guess) {
139	  $("btn-phish").disabled = $("btn-legit").disabled = true;
140	  const r = await apiAnswer(current.scenario_id, guess);
141	
142	  if (r.correct) correct++;
143	  const flags = r.red_flags
144	    ? `<p><b>Red flags:</b></p><ul>${r.red_flags.split(";").map((f) => `<li>${esc(f.trim())}</li>`).join("")}</ul>`
145	    : "";
146	  $("result").innerHTML = `
147	    <h3>${r.correct ? "✅ Correct!" : "❌ Not quite."} This one was <b>${r.game_answer}</b>.</h3>
148	    ${flags}<p>${esc(r.explanation)}</p>`;
149	  $("result").className = `card ${r.correct ? "good" : "bad"}`;
150	  $("progress").textContent = `${mode.toUpperCase()} · Round ${round} of ${ROUNDS} · ${correct} correct`;
151	  $("btn-next").textContent = round < ROUNDS ? "Next" : "See results";
152	  $("btn-next").classList.remove("hidden");
153	}
154	
155	$("btn-phish").addEventListener("click", () => answer("Phish"));
156	$("btn-legit").addEventListener("click", () => answer("Legit"));
157	$("btn-next").addEventListener("click", () => (round < ROUNDS ? nextRound() : finish()));
158	
159	// ---------- End of run ----------
160	async function finish() {
161	  const passed = correct >= TO_PASS;
162	  const badge = passed ? mode : null;
163	  await apiSaveScore($("username").value.trim(), correct * 100, badge);
164	
165	  $("end-title").textContent = passed ? `You earned ${BADGES[mode]}!` : `${correct} of ${ROUNDS} correct`;
166	  $("end-text").textContent = passed
167	    ? "Nice catch. Try the next mode!"
168	    : `You need ${TO_PASS} to earn ${BADGES[mode]}. Every round is new, so try again!`;
169	  show("end-screen");
170	  loadLeaderboard();
171	}
172	
173	$("btn-home").addEventListener("click", () => show("start-screen"));
174	
175	// ---------- Leaderboard ----------
176	async function loadLeaderboard() {
177	  const rows = await apiLeaderboard();
178	  $("leaderboard").innerHTML = rows.length
179	    ? rows.map((p) => {
180	        const icons = p.badges.map((b) => BADGES[b]?.split(" ")[0] || "").join(" ");
181	        const master = ["easy", "medium", "hard"].every((b) => p.badges.includes(b)) ? " 🏆" : "";
182	        return `<li><b>${esc(p.username)}</b> ${icons}${master} <span>${p.total_score} pts</span></li>`;
183	      }).join("")
184	    : '<li class="empty">No scores yet. Be the first!</li>';
185	}
186	
187	const ready = checkBackend();
188	ready.then(loadLeaderboard);

