1	// PhishSense backend
2	// Run: npm install, then npm start. Open http://localhost:3000
3	// Needs a .env file with DATABASE_URL, GEMINI_API_KEY, and GEMINI_MODEL (see .env.example)
4	
5	import "dotenv/config";
6	import express from "express";
7	import pg from "pg";
8	import { GoogleGenAI } from "@google/genai";
9	
10	const app = express();
11	app.use(express.json());
12	app.use(express.static("public")); // serves the game (public/index.html)
13	
14	const db = new pg.Pool({
15	  connectionString: process.env.DATABASE_URL,
16	  ssl: process.env.DATABASE_URL?.includes("localhost") ? false : { rejectUnauthorized: false },
17	});
18	const ai = process.env.GEMINI_API_KEY ? new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY }) : null;
19	
20	const MODES = ["easy", "medium", "hard"];
21	
22	// ---------- Gemini ----------
23	
24	// The exact fields we want back (same columns as the Google Sheet)
25	const SCENARIO_SCHEMA = {
26	  type: "object",
27	  properties: {
28	    channel: { type: "string", enum: ["email", "sms"] },
29	    sender: { type: "string" },
30	    subject: { type: "string" },
31	    body: { type: "string" },
32	    link: { type: "string" },
33	    game_answer: { type: "string", enum: ["Phish", "Legit"] },
34	    red_flags: { type: "string" },
35	    explanation: { type: "string" },
36	  },
37	  required: ["channel", "sender", "subject", "body", "link", "game_answer", "red_flags", "explanation"],
38	};
39	
40	const LEVELS = {
41	  easy: "Obvious. Phish: prizes you never entered, typos, ALL CAPS urgency, asks for card or Social Security numbers. Legit: friendly and specific, asks for nothing sensitive.",
42	  medium: "Realistic. Phish: lookalike domains, fake failed payments, fake sign-in pages, fake company IT. Legit: normal work requests about meetings, forms, or schedules.",
43	  hard: "Subtle. Phish: polished grammar, subdomain tricks like brand.com.fake-site.net, fake alerts from familiar-looking brands. Legit: HR, invoice, or report emails that look scary but come from @bayline-energy.com and ask for nothing risky.",
44	};
45	
46	async function askGemini(mode, examples) {
47	  const answer = Math.random() < 0.5 ? "Phish" : "Legit"; // keep the game balanced
48	  const channel = Math.random() < 0.3 ? "sms" : "email";
49	
50	  const prompt = `You write scenarios for PhishSense, a phishing-awareness game.
51	The player works at a fictional company, Bayline Energy.
52	Real company email: @bayline-energy.com. Real company phone: (404) 555-0100.
53	
54	Write ONE ${channel} message. Difficulty: ${mode}. The correct answer must be: ${answer}.
55	Difficulty guide: ${LEVELS[mode]}
56	
57	Rules:
58	- Only fictional companies, brands, and people. No real companies, banks, or government agencies.
59	- Phone numbers must look like (404) 555-01XX.
60	- For sms, leave subject empty and use a phone number as the sender.
61	- link is display text only (or empty). Use made-up domains.
62	- red_flags: short phrases separated by semicolons. Empty for Legit.
63	- explanation: 1 to 2 plain sentences anyone can understand.
64	
65	Examples of the style we want:
66	${JSON.stringify(examples)}`;
67	
68	  const call = ai.models.generateContent({
69	    model: process.env.GEMINI_MODEL,
70	    contents: prompt,
71	    config: { responseMimeType: "application/json", responseJsonSchema: SCENARIO_SCHEMA },
72	  });
73	  const timeout = new Promise((_, reject) => setTimeout(() => reject(new Error("timeout")), 6000));
74	  const response = await Promise.race([call, timeout]);
75	  const s = JSON.parse(response.text);
76	  if (s.game_answer !== answer) throw new Error("wrong answer type");
77	  return s;
78	}
79	
80	// ---------- Routes ----------
81	
82	// 1. Get a scenario (Gemini first, sheet backup if Gemini fails)
83	app.get("/api/scenario", async (req, res) => {
84	  const mode = MODES.includes(req.query.mode) ? req.query.mode : "easy";
85	  const seen = String(req.query.seen || "").split(",").map(Number).filter(Boolean); // avoid repeats in a run
86	  let row;
87	  try {
88	    if (!ai) throw new Error("no Gemini key");
89	    const { rows: examples } = await db.query(
90	      `SELECT channel, sender, subject, body, link, game_answer, red_flags, explanation
91	         FROM scenarios WHERE source = 'sheet' AND difficulty = $1 ORDER BY random() LIMIT 2`,
92	      [mode]
93	    );
94	    const s = await askGemini(mode, examples);
95	    const { rows } = await db.query(
96	      `INSERT INTO scenarios (source, channel, difficulty, sender, subject, body, link, game_answer, red_flags, explanation)
97	       VALUES ('gemini', $1, $2, $3, $4, $5, $6, $7, $8, $9) RETURNING *`,
98	      [s.channel, mode, s.sender, s.subject, s.body, s.link, s.game_answer, s.red_flags, s.explanation]
99	    );
100	    row = rows[0];
101	  } catch (err) {
102	    console.log(`Using backup scenario (${err.message})`);
103	    const { rows } = await db.query(
104	      `SELECT * FROM scenarios WHERE source = 'sheet' AND difficulty = $1 AND NOT (scenario_id = ANY($2::int[]))
105	        ORDER BY random() LIMIT 1`,
106	      [mode, seen]
107	    );
108	    row = rows[0];
109	  }
110	  // Only send what the player should see. The answer stays on the server.
111	  res.json({
112	    scenario_id: row.scenario_id, channel: row.channel, sender: row.sender,
113	    subject: row.subject, body: row.body, link: row.link,
114	  });
115	});
116	
117	// 2. Check an answer
118	app.post("/api/answer", async (req, res) => {
119	  const { scenario_id, guess } = req.body;
120	  const { rows } = await db.query(`SELECT * FROM scenarios WHERE scenario_id = $1`, [scenario_id]);
121	  if (!rows[0]) return res.status(404).json({ error: "Scenario not found" });
122	  const s = rows[0];
123	  res.json({
124	    correct: guess === s.game_answer,
125	    game_answer: s.game_answer,
126	    red_flags: s.red_flags,
127	    explanation: s.explanation,
128	  });
129	});
130	
131	// 3. Save a finished run (adds points, and the badge if they earned it)
132	app.post("/api/score", async (req, res) => {
133	  const username = String(req.body.username || "").trim().slice(0, 20);
134	  const points = Number(req.body.points) || 0;
135	  const badge = req.body.badge ? [req.body.badge] : [];
136	  if (!username) return res.status(400).json({ error: "Username required" });
137	  const { rows } = await db.query(
138	    `INSERT INTO scores (username, total_score, badges) VALUES ($1, $2, $3)
139	     ON CONFLICT (username) DO UPDATE SET
140	       total_score = scores.total_score + EXCLUDED.total_score,
141	       badges = ARRAY(SELECT DISTINCT unnest(scores.badges || EXCLUDED.badges)),
142	       updated_at = now()
143	     RETURNING *`,
144	    [username, points, badge]
145	  );
146	  res.json(rows[0]);
147	});
148	
149	// 4. Leaderboard (most badges first, then highest score)
150	app.get("/api/leaderboard", async (req, res) => {
151	  const { rows } = await db.query(
152	    `SELECT username, total_score, badges FROM scores
153	      ORDER BY cardinality(badges) DESC, total_score DESC LIMIT 10`
154	  );
155	  res.json(rows);
156	});
157	
158	const PORT = process.env.PORT || 3000;
159	app.listen(PORT, () => console.log(`PhishSense running at http://localhost:${PORT}`));
